function buildLanguage(index: number): Record<string, string> {
  return Object.fromEntries(rows.map((row) => [row[0], row[index + 1]]));
}

export const enhancedToolTranslations = {
  en: buildLanguage(0),
  tr: buildLanguage(1),
  de: buildLanguage(2),
  es: buildLanguage(3),
  fr: buildLanguage(4),
  ru: buildLanguage(5),
  zh: buildLanguage(6),
} as const;
